import json
import os

ctx = json.loads(os.environ['MIRAGE_POLICY_CTX'])
def answer():
    name = ctx['command']
    if name == 'touch':
        return {'kind': 'deny', 'reason': 'script says no'}
    if name == 'mkdir':
        return {'kind': 'ask', 'reason': 'mkdir needs a nod'}
    if name == 'rm' and ctx['env'].get('MODE') == 'safe':
        return {'kind': 'deny', 'reason': 'safe mode'}
    return None

print(json.dumps(answer()))

